let currentLang = localStorage.getItem('speedwayLang') || 'pl';

function t(key, params = {}) {
    const fallbackOrder = [currentLang, 'en', 'pl'];
    let str = key;

    for (const langName of fallbackOrder) {
        const langObj = i18n[langName];
        if (langObj && langObj[key] !== undefined) {
            str = langObj[key];
            break;
        }
    }

    for (let p in params) {
        str = str.replace(`{${p}}`, params[p]);
    }
    return str;
}

window.i18n = i18n;
window.currentLang = currentLang;
window.t = t;